import { expect, test } from '@playwright/test';
import { existsSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
const swf =
  process.env.BT3_SWF_FILE ?? resolve('../documented-bubble-tank-3/re/bt3/uncompressed.swf');
// The full post-merge suite has a larger hosted wall-clock budget. The pilot's
// inputs, simulated frames, frame cap and all earned-progression assertions stay fixed.
const playthroughTimeout = process.env.BT3_PLAYTHROUGH_LONG_RUN === '1' ? 600000 : 300000;
for (const native of [false, true])
  test(`${native ? 'SWF' : 'mock'} fresh game reaches the boss and win through ordinary controls`, async ({
    page,
  }, testInfo) => {
    test.setTimeout(playthroughTimeout);
    test.skip(native && !existsSync(swf), 'A local research SWF is required.');
    const errors: string[] = [];
    page.on('pageerror', (error) => errors.push(error.message));
    await page.goto('http://127.0.0.1:3102');
    await page.getByLabel('Fixture').selectOption('playthrough');
    if (native) await page.getByLabel('Original SWF').setInputFiles(swf);
    else await page.getByRole('button', { name: 'Use mock assets', exact: true }).click();
    const status = page.getByRole('status');
    await expect(status).toContainText('Ready', { timeout: playthroughTimeout - 20000 });
    const proof = JSON.parse((await status.getAttribute('data-playthrough'))!);
    const evidence = testInfo.outputPath('playthrough-evidence.json');
    writeFileSync(evidence, JSON.stringify(proof, null, 2));
    await testInfo.attach('playthrough-evidence', {
      path: evidence,
      contentType: 'application/json',
    });
    expect(proof).toMatchObject({
      seed: 17,
      mode: 'won',
      bossTriggered: true,
      bossDefeated: true,
      badge: true,
    });
    expect(proof.milestones[0]).toMatchObject({
      frame: 0,
      level: 0,
      life: 1,
      tank: 'A10000063',
      field: '0,0',
    });
    expect([...new Set(proof.upgrades.map((choice: { level: number }) => choice.level))]).toEqual([
      1, 2, 3, 4, 5, 6,
    ]);
    for (const key of ['kills', 'collected', 'shots', 'visited', 'completed'])
      expect(proof.stats[key]).toBeGreaterThan(0);
    expect(proof.frames).toBe(proof.stats.frames);
    expect(proof.helpClosed).toBe(1);
    const dialog = page.getByRole('dialog', {
      name: "You've Proven Yourself The Greatest!",
      exact: true,
    });
    await expect(dialog.locator('[data-win-age]')).toHaveAttribute('data-win-age', '63');
    await page
      .locator('#stage')
      .screenshot({ path: `test-results/${native ? 'swf' : 'mock'}-playthrough-win.png` });
    await page
      .locator('#run-history')
      .screenshot({ path: `test-results/${native ? 'swf' : 'mock'}-playthrough-history.png` });
    await dialog.getByRole('button', { name: 'Continue Your Game', exact: true }).click();
    await expect(page.locator('#stage')).toHaveAttribute('data-win-action', 'continue');
    expect(errors).toEqual([]);
  });
import type { TankDesign } from '../core/types';
// Retired Flash endpoints stay behind explicit interfaces. No hidden network requests,
// fake sign-in, or indefinitely pending server searches are used by the offline game.
export interface CommunityTanks {
  search(query: { avatar: boolean; classId?: number; gunPoints?: number }): Promise<TankDesign[]>;
  publish(tank: TankDesign): Promise<{ id: string }>;
  rate(id: string, rating: number): Promise<void>;
}
export interface Accounts {
  signIn(): Promise<{ id: string; name: string }>;
  signOut(): Promise<void>;
}
export interface PartsPacks {
  list(): Promise<{ id: string; name: string; installed: boolean }[]>;
  install(id: string): Promise<void>;
}
export interface Achievements {
  unlock(name: string): Promise<void>;
}
export class ServiceUnavailable extends Error {
  constructor(service: string) {
    super(`${service} is not connected.`);
    this.name = 'ServiceUnavailable';
  }
}
export const community: CommunityTanks = {
  search: async () => {
    throw new ServiceUnavailable('Community tank search');
  },
  publish: async () => {
    throw new ServiceUnavailable('Community tank sharing');
  },
  rate: async () => {
    throw new ServiceUnavailable('Community ratings');
  },
};
export const accounts: Accounts = {
  signIn: async () => {
    throw new ServiceUnavailable('Accounts');
  },
  signOut: async () => {},
};
export const partsPacks: PartsPacks = {
  list: async () => [],
  install: async () => {
    throw new ServiceUnavailable('Parts packs');
  },
};
export const achievements: Achievements = {
  unlock: async () => {
    /* Local medals are saved in Profile. Wire platform awards here. */
  },
};

export interface PlatformStats {
  report(name: string, value: number): Promise<void>;
}
export interface Advertisements {
  show(slot: 'preloader' | 'menu'): Promise<boolean>;
}
export const platformStats: PlatformStats = { report: async () => {} };
export const advertisements: Advertisements = { show: async () => false };

